using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
namespace PowerShapeBridge {
 internal static class OwnedSurfaceScaleTests {
  static void Need(bool ok,string e){if(!ok)throw new InvalidOperationException(e);}
  static Dictionary<string,object> Clone(object x){return Program.Json.Deserialize<Dictionary<string,object>>(Program.Json.Serialize(x));}
  sealed class Context:OwnedSurfaceTranslationTests.Context,OwnedSolidScale.IExecutionContext,OwnedSurfaceScaleMeasurements.IPhaseGuard {
   internal int FailPhase=-1;internal bool Selected,Applied;
   public object ClosestSolidFace(int n,double[] p){throw new InvalidOperationException("Surface scale requested SOLID closest face");}public object FaceNear(string f,double[] p){throw new InvalidOperationException("Unexpected membership fallback");}public object FacePoint(string f,double t,double u,bool n){throw new InvalidOperationException("Unexpected membership fallback");}
   public void ScalePhaseGuard(Dictionary<string,object> e,string name,int i,int windows){throw new InvalidOperationException("Surface called SOLID phase guard");}
   public void SurfaceScalePhaseGuard(Dictionary<string,object> e,string name,int i,int windows){Need(name=="Synthetic_21"&&Selected==(i>0)&&windows==1,"Surface phase target/count differs");}
   public void ScalePhase(SolidUniformScaleProgram p,int i){var cmd=p.Take(i);Need(p.Commands[0]=="SELECT CLEARLIST ADD SURFACE 'Synthetic_21'"&&p.Commands[9]=="VALUE 1.25","Wrong typed surface command");Calls++;if(i==FailPhase)throw new IOException("Lost return at explicit phase");if(i==0)Selected=true;if(i==10){Applied=true;if(Fault!="area"){var g=(Dictionary<string,object>)EntitySets.Inventory(Snapshot)[0]["geometry"];g["areaRaw"]=OwnedSurfaceTranslation.Number(g["areaRaw"])*1.25*1.25;}}if(i==12)Selected=false;}
   public override object SurfacePoints(string name,double ts,double te,int td,double us,double ue,int ud){int n=(td+1)*(ud+1);var p=Enumerable.Range(0,n*3).Select(i=>i+0.33333333333333337).ToArray();var normal=Enumerable.Range(0,n*3).Select(i=>i%3==2?1.0:0.0).ToArray();if(Applied){if(name=="Synthetic_21"){for(int i=0;i<p.Length;i++)p[i]=new[]{2.0,-3,4}[i%3]+1.25*(p[i]-new[]{2.0,-3,4}[i%3]);if(Fault=="point")p[0]+=1;if(Fault=="normal")normal[2]=-1;}else if(Fault=="other")p[0]+=1;}return new object[]{0,p,normal,Enumerable.Repeat(true,n).ToArray()};}
  }
  internal static int Run(){Need(File.Exists(Path.Combine(Program.Root,".surface-scale-fixture")),"Explicit isolated fake surface-scale marker required; never CAD.");var rows=new List<object>();int checks=0;
   foreach(string fault in new[]{"control","point","normal","other","area"}.Concat(Enumerable.Range(0,13).Select(i=>"phase"+i))){
    var f=new OwnedOperationPlanTests.Fixture(true,true,true);var c=new Context{Snapshot=Clone(f.Snapshot),Listing=Clone(f.Listing),Fault=fault,FailPhase=fault.StartsWith("phase")?int.Parse(fault.Substring(5)):-1};var args=new Dictionary<string,object>{{"entitySetId",f.SetId},{"entitySetSha256",Program.Hash(Path.Combine(f.Root,"entitysets",f.SetId+".json"))},{"bindingId",f.BindingId},{"bindingSha256",f.Parameters["bindingSha256"]},{"parameters",new Dictionary<string,object>{{"factor",1.25},{"centre",new[]{2,-3,4}},{"coordinateFrame","world"},{"lengthUnits","document_raw"},{"mode","scale_in_place"}}},{"surfaceGrid",new Dictionary<string,object>{{"tStart",1},{"tEnd",2},{"tDivisions",2},{"uStart",1},{"uEnd",2},{"uDivisions",3}}}};
    string preparedId=Guid.NewGuid().ToString("N");var p=OwnedSolidScale.Prepare(f.Root,preparedId,args,c,true);Need(Equals(p["state"],"owned_uniform_scale_prepared_observed")&&Equals(p["qualificationScope"],OwnedSurfaceScaleMeasurements.Scope),Program.Json.Serialize(p));string psha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",preparedId+".json"),p);var refs=new Dictionary<string,object>{{"ownedScaleId",preparedId},{"ownedScaleSha256",p["ownedScaleSha256"]},{"preparationReceiptSha256",psha},{"membershipBundleSha256",p["membershipBundleSha256"]}};
    string id=Guid.NewGuid().ToString("N");var e=OwnedSolidScale.Execute(f.Root,id,refs,c,true);bool partial=c.FailPhase>=0;Need(Equals(e["state"],partial?"owned_surface_scale_outcome_unknown":"owned_surface_scale_executed_unverified"),Program.Json.Serialize(e));Need(c.Calls==(partial?c.FailPhase+1:13),"Unexpected repeated/missing phase callback");checks++;
    string esha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",id+".json"),e);Need(Equals(OwnedSolidScale.Execute(f.Root,Guid.NewGuid().ToString("N"),refs,c,true)["state"],"owned_surface_scale_rejected_before_change"),"Scale replay reached callback");checks++;
    if(partial){rows.Add(new{fault,root=f.Root,executionId=id,calls=c.Calls});continue;}
    var j=NativeJournal.ForVerification(f.Root,id,(string)e["planSha256"]);var stamp=DateTime.UtcNow;if(stamp<=j.CommandReturnedUtc)stamp=j.CommandReturnedUtc.AddTicks(1);var o=c.Observation();o["timestampUtc"]=stamp.ToString("o");var w=c.Windows();w["state"]="documents_listed_verified";w["timestampUtc"]=stamp.AddTicks(1).ToString("o");string inspect=Guid.NewGuid().ToString("N"),listing=Guid.NewGuid().ToString("N"),vid=Guid.NewGuid().ToString("N");var proof=new Dictionary<string,object>{{"executionRequestId",id},{"executionReceiptSha256",esha},{"inspectionRequestId",inspect},{"inspectionSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",inspect+".json"),o)},{"listingRequestId",listing},{"listingSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",listing+".json"),w)},{"windowNumber",1},{"modelId",9},{"expiresUtc",DateTime.UtcNow.AddSeconds(150).ToString("o")}};
    var v=OwnedSolidScale.Verify(f.Root,vid,proof,c,false,true);Need(Equals(v["state"],fault=="control"?"owned_surface_scale_samples_match_unqualified":"owned_surface_scale_verification_rejected"),Program.Json.Serialize(v));Need(File.Exists(OwnedTranslation.FencePath(f.Root,(string)e["copyId"]))&&c.Calls==13,"Fake/failed surface verification released fence or replayed phase");string vsha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",vid+".json"),v);checks++;rows.Add(new{fault,root=f.Root,preparationId=preparedId,preparationSha256=psha,references=refs,executionId=id,executionSha256=esha,verificationId=vid,verificationSha256=vsha,verificationArguments=proof,verificationResult=v});
   }
   bool typed=false;try{new SolidUniformScaleProgram("1",1.25,new[]{2.0,-3,4},58);}catch(ArgumentException){typed=true;}Need(typed,"Arbitrary scale command target accepted");checks++;
   Directory.CreateDirectory(Path.Combine(Program.Root,"reports"));NativeJournal.Freeze(Path.Combine(Program.Root,"reports","surface-scale-tests.json"),new{state="passed",checks,rows,cadConnectionAttempted=false});Console.WriteLine("PASS: "+checks+" surface scale phase-stop/replay/UV/normal/area/other-object controls; no CAD.");return checks;
  }
 }
}
